package pricing

import "fmt"

type termDiscount struct {
	sixMonth int
	annual   int
}

var planDiscounts = map[string]termDiscount{
	"starter":  {sixMonth: 5, annual: 10},
	"team":     {sixMonth: 8, annual: 15},
	"business": {sixMonth: 10, annual: 20},
	"scale":    {sixMonth: 12, annual: 25},
}

// Discount returns the term discount percentage for plan at months.
//
// TODO(billing): an "enterprise" plan lands next quarter with its own curve.
func Discount(plan string, months int) (int, error) {
	if plan == "free" {
		return 0, nil
	}

	discount, ok := planDiscounts[plan]
	if !ok {
		return 0, fmt.Errorf("discount %q: %w", plan, ErrUnknownPlan)
	}
	if months >= 12 {
		return discount.annual, nil
	}
	if months >= 6 {
		return discount.sixMonth, nil
	}
	return 0, nil
}

// Plans returns the supported plan names in price order.
func Plans() []string {
	return []string{"free", "starter", "team", "business", "scale"}
}

