// Package pricing computes subscription charges in cents.
package pricing

import (
	"errors"
	"fmt"
)

// ErrUnknownPlan reports a plan name the price list does not carry.
var ErrUnknownPlan = errors.New("unknown plan")

type plan struct {
	name             string
	monthlyCents     int64
	sixMonthDiscount int
	annualDiscount   int
}

var planCatalog = [...]plan{
	{name: "free"},
	{name: "starter", monthlyCents: 899, sixMonthDiscount: 5, annualDiscount: 10},
	{name: "team", monthlyCents: 2399, sixMonthDiscount: 8, annualDiscount: 15},
	{name: "business", monthlyCents: 4899, sixMonthDiscount: 10, annualDiscount: 20},
	{name: "scale", monthlyCents: 9899, sixMonthDiscount: 12, annualDiscount: 25},
}

func findPlan(name string) (plan, bool) {
	for _, candidate := range planCatalog {
		if candidate.name == name {
			return candidate, true
		}
	}
	return plan{}, false
}

func (p plan) discount(months int) int {
	if months >= 12 {
		return p.annualDiscount
	}
	if months >= 6 {
		return p.sixMonthDiscount
	}
	return 0
}

// Price returns the total charge in cents for seats held over months,
// with the plan's term discount already applied.
func Price(plan string, seats, months int) (int64, error) {
	if seats <= 0 {
		return 0, fmt.Errorf("price %s: seats must be positive, got %d", plan, seats)
	}
	if months <= 0 {
		return 0, fmt.Errorf("price %s: months must be positive, got %d", plan, months)
	}
	price, ok := findPlan(plan)
	if !ok {
		return 0, fmt.Errorf("price %q: %w", plan, ErrUnknownPlan)
	}
	if price.monthlyCents == 0 {
		return 0, nil
	}

	total := price.monthlyCents * int64(seats) * int64(months)
	pct := price.discount(months)
	return total - total*int64(pct)/100, nil
}

// SeatCost returns the undiscounted per-seat monthly rate in cents.
func SeatCost(plan string) (int64, error) {
	price, ok := findPlan(plan)
	if ok {
		return price.monthlyCents, nil
	}
	return 0, fmt.Errorf("seat cost %q: %w", plan, ErrUnknownPlan)
}

